std::vector<int> source = {1, 2, 3};
// std::move casts source to an rvalue reference
std::vector<int> dest = std::move(source);

// Dest's internal resources are swapped with source's.
// source is now empty (moved-from state).

// --- Perfect Forwarding ---
template <typename T, typename... Args>
T create_object(Args&&... args) {
    // std::forward preserves the value category (lvalue/rvalue)
    return T(std::forward<Args>(args)...);
}

// --- Custom Move Assignment ---
class Resource {
    int* data;
public:
    Resource& operator=(Resource&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;  // Steal resource
            other.data = nullptr; // Nullify source
        }
        return *this;
    }
};
